parameters.jsCode:
const mode = $input.first().json.mode;
const now = $now;

const weekStart = String(now.startOf('week').minus(7, 'days').toMillis());
const weekEnd   = String(now.startOf('week').minus(1, 'millisecond').toMillis());

// --- Body Deals ---
const dealsBody = mode === 'PROD'
  ? {
      filterGroups: [{
        filters: [{
          propertyName: "closedate",
          operator: "BETWEEN",
          value: weekStart,
          highValue: weekEnd
        }]
      }],
      properties: ["dealname","amount","dealstage","closedate","pipeline"],
      limit: 100
    }
  : {
      properties: ["dealname","amount","dealstage","closedate","pipeline"],
      limit: 20
    };

// --- Body Tickets ---
const ticketsBody = mode === 'PROD'
  ? {
      filterGroups: [{
        filters: [{
          propertyName: "createdate",
          operator: "BETWEEN",
          value: weekStart,
          highValue: weekEnd
        }]
      }],
      properties: ["subject","hs_ticket_priority","hs_pipeline_stage","createdate","closed_date"],
      limit: 100
    }
  : {
      properties: ["subject","hs_ticket_priority","hs_pipeline_stage","createdate","closed_date"],
      limit: 20
    };

return [{
  json: {
    mode,
    bodyDeals:   JSON.stringify(dealsBody),
    bodyTickets: JSON.stringify(ticketsBody)
  }
}];

