    }
  },
  "required": ["points_cles", "tendances", "recommandations"]
}

parameters.jsCode:
// ============================================
// CODE EXTRACTOR - Agrégation 4 sources
// ============================================

// --- Séparation par type ---
const items = $input.all().map(i => i.json);
const deals         = items.filter(i => i.type === 'deal');
const tickets       = items.filter(i => i.type === 'ticket');
const ventesTerrain = items.filter(i => i.type === 'vente_terrain');
const objectifs     = items.filter(i => i.type === 'objectif');

// --- Helper montants ---
function parseAmount(raw) {
  if (!raw) return 0;
  if (typeof raw === 'number') return raw;
  const cleaned = String(raw).replace(/\s/g, '');
  if (/^\d{1,3}(\.\d{3})+$/.test(cleaned)) return Number(cleaned.replace(/\./g, ''));
  if (/^\d{1,3}(,\d{3})+$/.test(cleaned)) return Number(cleaned.replace(/,/g, ''));
  return Number(cleaned.replace(',', '.')) || 0;
}

// ============================================
// DEALS
// ============================================
let caSigne = 0, caPerdu = 0, pipelineEnCours = 0;
let nbWon = 0, nbLost = 0, nbOpen = 0;
const topDeals = [];

for (const d of deals) {
  const p = d.properties || {};
  const amount = parseAmount(p.amount);
  const stage = (p.dealstage || '').toLowerCase();

  if (stage === 'closedwon') {
    caSigne += amount; nbWon++;
    topDeals.push({ name: p.dealname, amount });
  } else if (stage === 'closedlost') {
    caPerdu += amount; nbLost++;
  } else {
    pipelineEnCours += amount; nbOpen++;
  }
}
topDeals.sort((a, b) => b.amount - a.amount);
const tauxConversion = deals.length ? Math.round((nbWon / deals.length) * 100) : 0;

// ============================================
// TICKETS
// ============================================
let ticketsOuverts = 0, ticketsFermes = 0, hautePrioriteOuverts = 0;
const parPriorite = {}, parStage = {}, ticketsCritiques = [];

for (const t of tickets) {
  const p = t.properties || {};
  const prio = (p.hs_ticket_priority || 'INCONNU').toUpperCase();
  const stage = (p.hs_pipeline_stage || 'INCONNU').toString();

  parPriorite[prio] = (parPriorite[prio] || 0) + 1;
  parStage[stage] = (parStage[stage] || 0) + 1;

  const isClosed = /closed|fermé|^4$/i.test(stage);
  if (isClosed) ticketsFermes++;
  else ticketsOuverts++;

  if (!isClosed && ['HIGH', 'URGENT'].includes(prio)) {
    hautePrioriteOuverts++;
    ticketsCritiques.push({
      sujet: p.subject || 'N/A',
      priorite: p.hs_ticket_priority || 'N/A',
      statut: p.hs_pipeline_stage || 'N/A'
    });
  }
}

// Liste numérotée (pour le resume / LLM)
let ticketsListe = '';
if (ticketsCritiques.length === 0) {
  ticketsListe = 'Aucun ticket critique ouvert.';
} else {
  ticketsCritiques.forEach((t, i) => {
    ticketsListe += `${i + 1}. ${t.sujet} | Priorité: ${t.priorite} | Statut: ${t.statut}\n`;
  });
}

// Liste à puces (pour Notion)
let listeTickets = '';
ticketsCritiques.forEach(t => {
  listeTickets += `• **${t.sujet}** — ${t.priorite} — statut ${t.statut}\n`;
});
if (listeTickets === '') listeTickets = '_Aucun ticket critique._';

// ============================================
// VENTES TERRAIN
// ============================================
let caTerrain = 0, caTerrainPaye = 0, caTerrainImpaye = 0, caTerrainAttente = 0;

for (const v of ventesTerrain) {
  const m = parseAmount(v.Montant);
  caTerrain += m;
  const statut = (v.Statut || '').toLowerCase();
  if (statut === 'payé' || statut === 'paye') caTerrainPaye += m;
  else if (statut === 'impayé' || statut === 'impaye') caTerrainImpaye += m;
  else caTerrainAttente += m;
}

// ============================================
// OBJECTIFS (filtre ultra-robuste)
// ============================================
const moisCourant = $now.toFormat('yyyy-MM');

function normaliserMois(raw) {
  if (raw === null || raw === undefined || raw === '') return '';
  // Nombre = timestamp en ms
  if (typeof raw === 'number') {
    try { return new Date(raw).toISOString().slice(0, 7); }
    catch (e) { return ''; }
  }
  // Date object
  if (raw instanceof Date) {
    return raw.toISOString().slice(0, 7);
  }
  // String
  const s = String(raw).trim();
  // Format ISO "2026-10-01T..." ou "2026-10-01"
  if (/^\d{4}-\d{2}/.test(s)) return s.slice(0, 7);
  // Tentative de parse générique
  const d = new Date(s);
  if (!isNaN(d.getTime())) return d.toISOString().slice(0, 7);
  return '';
}

const objectifsMois = objectifs.filter(o => normaliserMois(o.Mois) === moisCourant);
const objectifTotal = objectifsMois.reduce((s, o) => s + parseAmount(o['Objectif CA']), 0);

// ============================================
// CONSOLIDATION
// ============================================
const caTotal = caSigne + caTerrainPaye;
const atteinte = objectifTotal > 0 ? Math.round((caTotal / objectifTotal) * 100) : 0;

// ============================================
// RESUME POUR LE LLM
// ============================================
const resume = `
RAPPORT HEBDOMADAIRE - DONNÉES BRUTES

=== VENTES CRM (${deals.length} deals) ===
- CA signé : ${caSigne.toFixed(2)} €
- CA perdu : ${caPerdu.toFixed(2)} €
- Pipeline en cours : ${pipelineEnCours.toFixed(2)} €
- Gagnés : ${nbWon} | perdus : ${nbLost} | en cours : ${nbOpen}
- Taux de conversion : ${tauxConversion}%
- Top 3 : ${topDeals.slice(0, 3).map(d => `${d.name} (${d.amount.toFixed(0)} €)`).join(', ') || 'aucun'}

=== VENTES TERRAIN (${ventesTerrain.length} ventes) ===
- CA terrain total : ${caTerrain.toFixed(2)} €
- Payé : ${caTerrainPaye.toFixed(2)} € | Impayé : ${caTerrainImpaye.toFixed(2)} € | En attente : ${caTerrainAttente.toFixed(2)} €

=== SUPPORT (${tickets.length} tickets) ===
- Ouverts : ${ticketsOuverts} | Fermés : ${ticketsFermes}
- Haute priorité ouverts : ${hautePrioriteOuverts}
- Par priorité : ${Object.entries(parPriorite).map(([k, v]) => `${k}=${v}`).join(', ')}

=== DÉTAIL DES TICKETS CRITIQUES ===
${ticketsListe}
=== OBJECTIFS ${moisCourant} ===
- Objectif CA : ${objectifTotal.toFixed(2)} €
- CA total réalisé (CRM + terrain payé) : ${caTotal.toFixed(2)} €
- Atteinte : ${atteinte}%
`.trim();

// ============================================
// RETURN
// ============================================
return [{
  json: {
    resume,
    listeTickets,
    ticketsListe,
    caSigne,
    caPerdu,
    pipelineEnCours,
    tauxConversion,
    ticketsOuverts,
    ticketsFermes,
    hautePrioriteOuverts,
    caTerrain,
    caTerrainPaye,
    nbVentesTerrain: ventesTerrain.length,
    caTerrainImpaye,
    caTerrainAttente,
    objectifTotal,
    caTotal,
    atteinte,
    ticketsCritiques,
  }
}];
